//! Deterministic skill prefilter for two-phase selection.//!//! The first phase of skill selection is entirely deterministic -- no LLM involvement,//! no skill content in context. This prevents circular manipulation where a loaded//! skill could influence which skills get loaded.//!//! Scoring://! - Keyword exact match: 10 points (capped at 30 total)//! - Keyword substring match: 5 points (capped at 30 total)//! - Tag match: 3 points (capped at 15 total)//! - Regex pattern match: 20 points (capped at 40 total)use crate::skills::LoadedSkill;/// Default maximum context tokens allocated to skills.pub const MAX_SKILL_CONTEXT_TOKENS: usize = 4000;/// Maximum keyword score cap per skill to prevent gaming via keyword stuffing./// Even if a skill has 20 keywords, it can earn at most this many keyword points.const MAX_KEYWORD_SCORE: u32 = 30;/// Maximum tag score cap per skill (parallel to keyword cap).const MAX_TAG_SCORE: u32 = 15;/// Maximum regex pattern score cap per skill. Without a cap, 5 patterns at/// 20 points each could yield 100 points, dominating keyword+tag scores.const MAX_REGEX_SCORE: u32 = 40;/// Result of prefiltering with score information.#[derive(Debug)]pub struct ScoredSkill<'a> {    pub skill: &'a LoadedSkill,    pub score: u32,}/// Select candidate skills for a given message using deterministic scoring.////// Returns skills sorted by score (highest first), limited by `max_candidates`/// and total context budget. No LLM is involved in this selection.